<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Account activity</title>
  <link rel="stylesheet" href="activity.css">
</head>
<body>
  <main class="activity">
    <h1>Account activity</h1>
    <p class="intro">Every sign-in and account change from the last 90 days, newest first.</p>

    <table id="activity-table">
      <thead>
        <tr>
          <th>When</th>
          <th>Event</th>
          <th>Device</th>
          <th>Location</th>
          <th>IP</th>
          <th>Details</th>
        </tr>
      </thead>
      <tbody></tbody>
    </table>
  </main>
  <script src="activity-data.js"></script>
  <script src="activity.js"></script>
</body>
</html>
=== activity.css
body {
  font-family: system-ui, sans-serif;
  margin: 0;
  background: #f6f7f9;
}

.activity {
  max-width: 960px;
  margin: 3rem auto;
  padding: 2rem;
  background: #fff;
  border-radius: 8px;
}

.activity h1 {
  margin-top: 0;
  font-size: 1.5rem;
}

#activity-table {
  width: 100%;
  border-collapse: collapse;
}

#activity-table th,
#activity-table td {
  text-align: left;
  padding: 0.5rem;
  border-bottom: 1px solid #e3e5e8;
}
=== activity.js
// Renders every event as one table row, in API order.
const tbody = document.querySelector('#activity-table tbody');
for (const event of window.ACTIVITY_EVENTS) {
  const row = document.createElement('tr');
  for (const value of [
    new Date(event.when).toLocaleString(),
    event.type,
    event.device,
    event.location,
    event.ip,
    event.detail,
  ]) {
    const cell = document.createElement('td');
    cell.textContent = value;
    row.appendChild(cell);
  }
  tbody.appendChild(row);
}
